import{_ as o,o as t,c as a,a3 as r}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"阻塞|轮询输入输出网络流量理论","description":"","frontmatter":{"translationSource":{"title":"阻塞|轮询输入输出网络流量理论","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=sBuLtJ1gTFsoEdbw8DPPKH","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/network-flow-theory-for-blocking-round-robin-inputs-and-outputs"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/network-flow-theory-for-blocking-round-robin-inputs-and-outputs"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/network-flow-theory-for-blocking-round-robin-inputs-and-outputs"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/network-flow-theory-for-blocking-round-robin-inputs-and-outputs"}]]},"headers":[],"relativePath":"zh/network-flow-theory-for-blocking-round-robin-inputs-and-outputs.md","filePath":"zh/page-sBuLtJ1gTFsoEdbw8DPPKH.md"}'),n={name:"zh/network-flow-theory-for-blocking-round-robin-inputs-and-outputs.md"};function d(i,e,s,l,p,c){return t(),a("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><h1 id="阻塞-轮询输入输出网络流量理论" tabindex="-1">阻塞|轮询输入输出网络流量理论 <a class="header-anchor" href="#阻塞-轮询输入输出网络流量理论" aria-label="Permalink to &quot;阻塞\\|轮询输入输出网络流量理论&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>本页内容更新：</span><a href="/endfield-skydoc/zh/changelog/capture-2026-11-14T07-40-38-165Z-a1e1e549" title="网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。" aria-label="本页内容更新：2026-11-14. 网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。"><time datetime="2026-11-14T07:40:39.277Z">2026-11-14</time></a><span class="page-updated-zone">（北京时间）</span></p><blockquote><p>源页面 ID：<code>sBuLtJ1gTFsoEdbw8DPPKH</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=sBuLtJ1gTFsoEdbw8DPPKH" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>实际物理系统：在终末地物流系统基础上，忽略bug存在时的物流系统。</p><p><a href="/endfield-skydoc/zh/theory-of-the-actual-physical-laws">实际物理规律的理论</a></p><p>理想系统：由输入、输出、分流、汇流节点组成的网络，遵循对实际物理系统的一部分模拟规律（轮询规律，连接限制，流量限制等），忽略相位与边长的影响，只存在单一物质，是一套在连续基础上建立的系统。</p><p><a href="/endfield-skydoc/zh/flow-theory-for-idealized-logistics-systems">理想系统的流量理论</a> · <a href="/endfield-skydoc/zh/flow-rate-logistics-blueprint-library">流量物流蓝图库</a></p><p><a href="https://docs.qq.com/aio/DZXhhTUp6WU1Yd3Ba?scene=7ba40f91fa61839ac09fca8dKJTAx1&amp;p=GzlRUGEnEkorT2H6NOunIL" target="_blank" rel="noreferrer">物流结构分类汇总</a></p><p>理想系统++：在理想系统基础上添加优先级（优先输出与优先输入）与假定存在的限速器节点的存在（例如将复杂的1/5限流器做成一组n/5节点，将多节点压成单节点，简化图结构）。</p><p>理想系统#：在理想系统++的基础上，添加不同种类物品与工厂节点，将复杂的汇流、分流节点简化为限速分流节点（进一步简化图结构。但是依旧忽略边容量、边长（延迟）等元素，禁止了混带混管，并依旧在连续基础上运算。</p><p><a href="/endfield-skydoc/zh/centered-on-adaptive-production-lines">以自适应产线为核心</a></p></div>',1)])])}const f=o(n,[["render",d]]);export{u as __pageData,f as default};
